x_comment(x_FormulaArgPositionFn,"#$FormulaArgPositionFn is a #$VariableArityFunction that takes as its arguments instances of #$NonNegativeInteger. It returns a #$FormulaArgPosition with the arg position as elements in the list. Since the argument position might be nested inside the formula, #$FormulaArgPositionFn represents the position using a variable number of non-negative integers. For example, to represent the argument position of #$BodyOfWater in the formula (#$and (#$isa #$PacificOcean #$BodyOfWater) (#$bordersOn #$PacificOcean #$UnitedStatesOfAmerica)), use (#$FormulaArgPositionFn 1 2) (which denotes (#$TheList 1 2), an instance of #$FormulaArgPosition), where \"1\" represents the position occupied by (#$isa #$PacificOcean #$BodyOfWater) and \"2\" represents the position occupied by #$BodyOfWater.") :- x_cid(a65b1273a542ec).
xc_microtheory(a65b1273a542ec,x_GKEFormulaTemplatesMt).
