x_comment(x_FormulaReplacementSelectionOption,"A collection of individual options used in selecting what term should be replaced by default in a formula. Instances of #$FormulaReplacementSelectionOption include #$Atomic-SelectionOption and #$NonAtomic-SelectionOption. If the replacement selection option for a formula template is #$Atomic-SelectionOption, then, by default, atomic terms in replaceable formula positions will be independently selectable for replacement. If the replacement selection option is #$NonAtomic-SelectionOption, then, by default, replaceable non atomic terms will be selectable for replacement. See also #$formulaTemplateSelectionOption and #$formulaTemplateArgSelectionOption.") :- x_cid(a65b1273a54306).
xc_microtheory(a65b1273a54306,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54306,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54306,49).
xc_kb_names(a65b1273a54306,[]).
xc_mapping_rows(a65b1273a54306,[]).
x_comment(x_formulaTemplateSelectionOption,"(#$formulaTemplateSelectionOption TEMPLATE OPT) means that formula template TEMPLATE has, by default, selection option OPT. Therefore, every replaceable position in TEMPLATE will have OPT. This does not mean that no other options are necessarily available, it just means that OPT will be the default selection option. See #$FormulaReplacementSelectionOption. To specify a selection option about a particular argument position, see #$formulaTemplateArgSelectionOption.") :- x_cid(a65b1273a54307).
xc_microtheory(a65b1273a54307,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54307,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54307,50).
xc_kb_names(a65b1273a54307,[]).
xc_mapping_rows(a65b1273a54307,[]).
x_comment('x_NonAtomic-SelectionOption',"An instance of #$FormulaReplacementSelectionOption. If the replacement selection option is #$NonAtomic-SelectionOption, then, by default, replaceable (#$positionInFormulaTemplateIsReplaceable) non atomic terms (#$CycLNonAtomicReifiedTerm) will be selectable for replacement. For example, in (#$genls (#$JuvenileFn #$Dog) #$Animal), if the arg position containing (#$JuvenileFn #$Dog) were replaceable, the entire NART (#$JuvenileFn #$Dog) would, by default, be selectable for replacement (as opposed to selecting each #$CycLAtomicTerm #$JuvenileFn and #$Dog separately). See #$formulaTemplateSelectionOption and #$formulaTemplateArgSelectionOption.") :- x_cid(a65b1273a54308).
xc_microtheory(a65b1273a54308,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54308,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54308,51).
xc_kb_names(a65b1273a54308,[]).
xc_mapping_rows(a65b1273a54308,[]).
x_comment('x_Atomic-SelectionOption',"An instance of #$FormulaReplacementSelectionOption. If the replacement selection option for a formula template is #$Atomic-SelectionOption, then, by default, atomic terms (#$CycLAtomicTerm) in replaceable positions (#$positionInFormulaTemplateIsReplaceable) will be independently selectable for replacement. For example, in (#$genls (#$JuvenileFn #$Dog) #$Animal), if the arg position containing (#$JuvenileFn #$Dog) were replaceable, #$JuvenileFn and #$Dog would, by default, each be independently selected to replace with another term (as opposed to selecting the entire #$CycLNonAtomicReifiedTerm (#$JuvenileFn #$Dog)). See #$formulaTemplateSelectionOption and #$formulaTemplateArgSelectionOption.") :- x_cid(a65b1273a54309).
xc_microtheory(a65b1273a54309,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54309,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54309,52).
xc_kb_names(a65b1273a54309,[]).
xc_mapping_rows(a65b1273a54309,[]).
x_comment(x_formulaTemplateArgSelectionOption,"(#$formulaTemplateArgSelectionOption TEMPLATE ARG OPT) means that arg position ARG in formula template TEMPLATE has, by default, selection option OPT. This does not mean that no other options are necessarily available, it just means that OPT will be the default selection option. If an arg position in a formula template does not have a #$formulaTemplateArgSelectionOption assertion, and the formula template does not have a #$formulaTemplateSelectionOption assertion, then, by default, the arg position in that template will have #$NonAtomic-SelectionOption.") :- x_cid(a65b1273a5430a).
xc_microtheory(a65b1273a5430a,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430a,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a5430a,53).
xc_kb_names(a65b1273a5430a,[]).
xc_mapping_rows(a65b1273a5430a,[]).
x_comment(x_focalTermPositionForFormulaTemplate,"(#$focalTermPositionForFormulaTemplate TEMPLATE POS TOPIC) means that the term in position POS is the focal term in TEMPLATE for TOPIC. The same template can have a different focal term for different topics. Within one topic, the position(s) denoted as focal term(s) will always refer to the same instance. For example, if (#$formulaForFormulaTemplate HasMembersTemplate (#$hasMembers (#$SomeExampleFn #$Organization) (#$SomeExampleFn #$Person))), then HasMembersTemplate might be an instance of a #$FormulaTemplateTopicType, PersonTopic, where (#$templateTypeForFocalTermType #$Person PersonTopic). In this case, (#$focalTermPositionForFormulaTemplate HasMembersTemplate (#$FormulaArgPositionFn 2) HasMembersTemplate). On the other hand, HasMembersTemplate might also be an instance of a #$FormulaTemplateTopicType, OrganizationTopic, where (#$templateTypeForFocalTermType #$Organization OrganizationTopic). In this case, (#$focalTermPositionForFormulaTemplate HasMembersTemplate (#$FormulaArgPositionFn 1) OrganizationTopic).") :- x_cid(a65b1273a5430b).
xc_microtheory(a65b1273a5430b,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430b,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a5430b,54).
xc_kb_names(a65b1273a5430b,[]).
xc_mapping_rows(a65b1273a5430b,[]).
x_comment(x_constraintOnReplacement,"(#$constraintOnReplacement TEMPLATE POS SET-OR-COLLECTION) means that any term that will replace the term in POS of TEMPLATE must be a member of SET-OR-COLLECTION.") :- x_cid(a65b1273a5430c).
xc_microtheory(a65b1273a5430c,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430c,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a5430c,55).
