xc_mapping_rows(a65b1273a5430c,[]).
x_comment(x_candidateReplacementForPosition,"(#$candidateReplacementForPosition TEMPLATE POS SET-OR-COLLECTION) means that for formula template TEMPLATE, the term that is in arg position POS of the formula can be replaced by any member of SET-OR-COLLECTION. It also means that (#$positionInFormulaTemplateIsReplaceable TEMPLATE POS).") :- x_cid(a65b1273a5430d).
xc_microtheory(a65b1273a5430d,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430d,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a5430d,56).
xc_kb_names(a65b1273a5430d,[]).
xc_mapping_rows(a65b1273a5430d,[]).
x_comment(x_templateTopicAssertion,"(#$templateTopicAssertion TOPIC FORMULA POS) means that, when dealing with TOPIC, the user can assume that FORMULA is already known to be true. POS denotes the argument position in FORMULA that should be replaced by the focal term for the topic (see #$templateTypeForFocalTermType). For example, if (#$templateTypeForFocalTermType #$Person PersonTopicType) then Cyc should know that (#$isa X #$Person), where X should be replaced by the appropriate instance of #$Person. Therefore, (#$templateTopicAssertion PersonTopicType (#$isa X #$Person) (#$FormulaArgPositionFn 1)). Note that the above example is incorporated in a rule, so it is unnecessary to assert, but #$templateTopicAssertion can also be used for other assertions, e.g. for lexical information.") :- x_cid(a65b1273a5430e).
xc_microtheory(a65b1273a5430e,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430e,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a5430e,57).
xc_kb_names(a65b1273a5430e,[]).
xc_mapping_rows(a65b1273a5430e,[]).
x_comment(x_formulaTemplateExample,"(#$formulaTemplateExample TEMPLATE TOPIC FORMULA) means that, when dealing with TOPIC, FORMULA is a good example of a formula that can be made using TEMPLATE.") :- x_cid(a65b1273a5430f).
xc_microtheory(a65b1273a5430f,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a5430f,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
