xc_mapping_rows(a65b1273a5430f,[]).
x_comment(x_templateTopicPrefix,"(#$templateTopicPrefix TOPIC PREFIX) means that new constants created using templates that are instances of TOPIC should have the prefix PREFIX. This predicate is useful when the name of the constant is unimportant. It provides a prefix to be used by all constants of a particular topic. Typically, some unique string will be added to the prefix to ensure that the new constant has a unique name.") :- x_cid(a65b1273a54310).
xc_microtheory(a65b1273a54310,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54310,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54310,59).
xc_kb_names(a65b1273a54310,[]).
xc_mapping_rows(a65b1273a54310,[]).
x_comment(x_TemplateFromTestQueryFn,"An instance of #$UnaryFunction, #$IndividualDenotingFunction, and #$ReifiableFunction. #$TemplateFromTestQueryFn takes an instance of #$CycLQuerySpecification and returns the unique #$FormulaTemplate for which the #$InferenceSentenceParameter of the query specification is its formula. (See #$formulaForFormulaTemplate.)") :- x_cid(a65b1273a54311).
xc_microtheory(a65b1273a54311,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54311,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54311,60).
xc_kb_names(a65b1273a54311,[]).
xc_mapping_rows(a65b1273a54311,[]).
x_comment(x_focalTermIntroduction,"(#$focalTermIntroduction TOPIC TEMPLATE) means that TEMPLATE introduces the focal term to be used for TOPIC. The term(s) entered into the replaceable position(s) in TEMPLATE is/are the name of a new constant, which will be the focal term for templates of TOPIC. This new constant is an instance of the collection denoted in #$templateTypeForFocalTermType. All the other templates in TOPIC have their focal term position (#$focalTermPositionForFormulaTemplate) replaced with this new constant. The replaceable term(s) in TEMPLATE must be replaced before any other templates in TOPIC can be asserted. If there is more than one #$focalTermIntroduction assertion for a single topic, then the replacements for the replaceable terms in those templates are combined to form one constant name. The ordering is determined using #$higherPriorityTemplateForType. To denote a focal term without #$focalTermIntroduction, see #$templateTopicPrefix.") :- x_cid(a65b1273a54312).
xc_microtheory(a65b1273a54312,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54312,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54312,61).
xc_kb_names(a65b1273a54312,[]).
xc_mapping_rows(a65b1273a54312,[]).
x_comment(x_formulaTemplatizer,"(#$formulaTemplatizer TEMPLATE CYCLIST) means that CYCLIST is responsible for creating or maintaining TEMPLATE. This does not mean that CYCLIST is necessarily responsible for the assertion or query formula used by TEMPLATE. To find the responsible cyclist for a particular query, see #$testResponsibleCyclist.") :- x_cid(a65b1273a54313).
xc_microtheory(a65b1273a54313,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54313,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54313,62).
xc_kb_names(a65b1273a54313,[]).
xc_mapping_rows(a65b1273a54313,[]).
x_comment(x_formulaTemplateContinuation,"(#$formulaTemplateContinuation TEMPLATE1 TEMPLATE2 TOPIC) means that, when working in the context of TOPIC, TEMPLATE2 is a good follow up to TEMPLATE1. More specifically, if one is making assertions and can fill in the values for TEMPLATE1, then one may also be able to fill in the value for TEMPLATE2. For example, if while describing an instance of terrorist, one asserts that the terrorist died on a particular date, it would be appropriate to then be prompted to assert the cause of death.") :- x_cid(a65b1273a54314).
xc_microtheory(a65b1273a54314,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54314,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54314,63).
xc_kb_names(a65b1273a54314,[]).
xc_mapping_rows(a65b1273a54314,[]).
x_comment(x_templateReplacementsInvisibleForPosition,"(#$templateReplacementsInvisibleForPosition TEMPLATE POS) means that all of the potential replacements for POS in TEMPLATE should remain invisible to the user. They will still be replacements, they will just not appear in the user interface. This is useful to assert when the list of replacements is especially long or unhelpful (e.g. all positive integers).") :- x_cid(a65b1273a54315).
xc_microtheory(a65b1273a54315,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54315,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54315,64).
xc_kb_names(a65b1273a54315,[]).
xc_mapping_rows(a65b1273a54315,[]).
x_comment(x_templateCoversQuery,"(#$templateCoversQuery TEMPLATE QUERY) means that QUERY can be asked using TEMPLATE, even though TEMPLATE does not have QUERY as the #$querySpecificationForFormulaTemplate. In other words, TEMPLATE was created using a different query specification, but the template also covers QUERY. For example, a template made from the query (#$objectHasColor ?OBJ #$RedColor) might allow #$RedColor to be replaced with #$BlueColor, so this template would also cover the second query (#$objectHasColor ?OBJ #$BlueColor), and it would not make sense to make a separate template out of the second query.") :- x_cid(a65b1273a54316).
xc_microtheory(a65b1273a54316,x_GKEFormulaTemplatesMt).
xc_source_file(a65b1273a54316,'c:/snet/petta/repos/openworld_dr/KBs/fire/flat-files/nextkb/GKEFormulaTemplatesMt.krf').
xc_source_line(a65b1273a54316,65).
