xc_mapping_rows(a65b1273a54316,[]).
x_comment('x_FormulaTemplate-ProblematicQuery',"Instances of #$FormulaTemplate-ProblematicQuery are query templates such that the #$querySpecificationForFormulaTemplate is somehow problematic. For example, the query may not be returning any results, or the results returned may be incorrect or unpresentable. The queries for these template need further work. The user interface may choose to disallow users from running these queries.") :- x_cid(a65b1273a54317).
xc_microtheory(a65b1273a54317,x_GKEFormulaTemplatesMt).
